#!/usr/bin/env python3
"""Regenerate the local icon subset from sources.json (Python 3 and curl)."""
import concurrent.futures
import json
from pathlib import Path
import subprocess
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parent
SVG_NS = "http://www.w3.org/2000/svg"
ET.register_namespace("", SVG_NS)
TAGS = {"svg", "g", "path", "rect", "circle", "ellipse", "line", "polyline", "polygon"}
ATTRS = {
    "width", "height", "viewBox", "fill", "fill-rule", "clip-rule", "opacity",
    "stroke", "stroke-width", "stroke-linecap", "stroke-linejoin", "stroke-miterlimit",
    "d", "x", "y", "x1", "y1", "x2", "y2", "cx", "cy", "r", "rx", "ry",
    "points", "transform",
}


def fetch(library, source_path):
    url = (f'https://raw.githubusercontent.com/{library["repository"]}/'
           f'{library["revision"]}/{source_path}')
    return subprocess.check_output([
        "curl", "--fail", "--location", "--silent", "--show-error",
        "--connect-timeout", "10", "--max-time", "45", "--retry", "2", "--retry-all-errors", url,
    ]).decode("utf-8")


def normalize(text, transform=None):
    svg = ET.fromstring(text)
    if transform:
        # Retain the upstream inner information mark, omitting its outer ring.
        path = svg.find(f"{{{SVG_NS}}}path")
        prefix = transform["removePathPrefix"]
        if path is None or not path.attrib.get("d", "").startswith(prefix):
            raise ValueError("Pinned information icon geometry changed")
        path.set("d", transform["replacementStart"] + path.attrib["d"][len(prefix):] + transform.get("append", ""))
    if svg.tag != f"{{{SVG_NS}}}svg" or "viewBox" not in svg.attrib:
        raise ValueError("Expected an SVG with a viewBox")
    for node in svg.iter():
        if node.tag not in {f"{{{SVG_NS}}}{tag}" for tag in TAGS}:
            raise ValueError(f"Unexpected SVG element: {node.tag}")
        if set(node.attrib) - ATTRS:
            raise ValueError(f"Unexpected SVG attributes: {node.attrib}")
        for value in node.attrib.values():
            if "url(" in value.lower():
                raise ValueError("External SVG references are not supported")
        node.text = None
        node.tail = None
    svg.attrib.pop("width", None)
    svg.attrib.pop("height", None)
    svg.attrib.setdefault("fill", "currentColor")
    return ET.tostring(svg, encoding="unicode")


def main():
    sources = json.loads((ROOT / "sources.json").read_text())
    roles = sources["roles"]
    libraries = sources["libraries"]
    if not all(len(names) == len(libraries) for names in roles.values()):
        raise ValueError("Every role must map to every library")
    data = {"roles": list(roles), "libraries": {}}
    for index, (key, library) in enumerate(libraries.items()):
        names = {role: values[index] for role, values in roles.items()}
        paths = {name: library["path"].format(name=name) for name in set(names.values())}
        with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
            raw = dict(zip(paths, pool.map(lambda name: fetch(library, paths[name]), paths)))
        transforms = sources.get("transforms", {}).get(key, {})
        icons = {role: normalize(raw[name], transforms.get(role)) for role, name in names.items()}
        # Write only after the full family has downloaded and passed validation.
        license_text = fetch(library, library["license"])
        (ROOT / f"LICENSE-{key}").write_text(license_text)
        data["libraries"][key] = {"name": library["name"], "icons": icons}
        print(f'{key}: {len(icons)} roles from {library["revision"]}')
    output = (
        "/* Generated by regenerate.py from pinned official SVGs. See sources.json, README.md and LICENSE-*. */\n"
        '(function (global) {\n  "use strict";\n  global.ABKIconData = '
        + json.dumps(data, ensure_ascii=False, separators=(",", ":"))
        + ";\n})(window);\n"
    )
    (ROOT / "icon-data.js").write_text(output)


if __name__ == "__main__":
    main()
